struct Parser {
    let toks: [Token]; var i = 0          // eat(_:) consumes a token or throws ParseError.expected
    mutating func expr() throws -> Node {
        var left = try term()
        while toks[i].kind == .plus || toks[i].kind == .minus {  // loop, not left recursion
            left = .binary(try eat(toks[i].kind), left, try term())
        }
        return left
    }
}
